def optimize_seating(M, N, K, L, D, chatting_pairs):
    # Initialize the number of chatting pairs that can be separated by each possible position as a 2D array
    num_separated = [[0 for _ in range(M)] for _ in range(N)]

    # Loop through each chatting pair
    for pair in chatting_pairs:
        # Get the positions of the pair
        (xi, yi) = pair[0]
        (pi, qi) = pair[1]

        # Check if the pair is separated by an aisle
        for i in range(1, K+1):
            for j in range(1, L+1):
                if xi + i < M and yi + j < N and xi - i >= 0 and yi - j >= 0:
                    # Check if the pair is separated by a horizontal or vertical aisle
                    if xi + i != pi:
                        num_separated[xi + i][yi + j] += 1
                    if yi + j != qi:
                        num_separated[xi - i][yi - j] += 1

    # Find the maximum number of chatting pairs that can be separated
    max_separated = max([max(row) for row in num_separated])

    # Loop through each position and check if it has the maximum number of separated chatting pairs
    optimal_rows = []
    optimal_cols = []
    for i in range(M):
        for j in range(N):
            if num_separated[i][j] == max_separated:
                optimal_rows.append(i)
                optimal_cols.append(j)

    # Return the optimal row and column indices as a tuple
    return ' '.join(str(x) for x in optimal_rows), ' '.join(str(x) for x in optimal_cols)
