def max_energy(beads):
    n = len(beads)
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(n):
        for j in range(i + 1, n + 1):
            if j == n: dp[i][j] = dp[i][j - 1] + beads[i] * beads[0]
            else: dp[i][j] = max(dp[i][j - 1] + beads[i] * beads[j], dp[i + 1][j] + beads[i] * beads[j])

    return dp[0][n]
```

