def polynomial_to_string(n, coeffs):
    result = ''
    for power, coeff in enumerate(coeffs):
        if coeff == 0:
            continue
        else:
            term = ''
            if coeff < 0:
                term += '-'
            elif result != '':
                term += '+'
            abs_coeff = abs(coeff)
            if abs_coeff != 1 or power == 0:
                term += str(abs_coeff)
            if power > 0:
                term += 'x'
                if power > 1:
                    term += '^' + str(power)
            result += term
    return result
```

