def count_partitions(n, k, x):
    dp = [[0] * (x + 1) for _ in range(k + 1)]
    dp[0][0] = 1
    for i in range(1, k + 1):
        for j in range(1, x + 1):
            dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j]
    return dp[k][x]
