def count_sequences(n, last, memo):
    if n in memo:
        return memo[n]
    if n == last:
        return 1
    count = 0
    for i in range(1, int(last / 2) + 1):
        if last % i == 0:
            count += count_sequences(n + 1, i, memo)
    memo[n] = count
    return count
