def count_coprime_pairs(x0, y0):
    count = 0
    for a in range(1, y0 // x0 + 1):
        b = y0 // x0 // a
        if a == b:
            count += 1
        elif a % b == 0 and x0 % a == 0:
            count += 2
    return count
